TERMS = [
# ============================ DATA & DATABASES ============================
{"term": "Database", "branch": "Data & Databases", "de": "Datenbank", "tags": ["fundamental"], "wikipedia": "Database",
 "def": "An organised collection of structured data, managed by a **DBMS** (database management system) that handles storage, querying, concurrency, and durability.",
 "context": "The word is used loosely for both the data and the engine managing it. The fundamental tension running through the whole field: how much structure and consistency you enforce up front versus how much speed and scale you buy by relaxing them.",
 "see_also": ["RDBMS", "NoSQL", "SQL", "Transaction", "Index"]},

{"term": "RDBMS", "branch": "Data & Databases", "aliases": ["Relational Database Management System", "Relational Database"],
 "tags": ["fundamental"], "wikipedia": "Relational database",
 "def": "A database organising data into **relations** (tables of rows and columns) with enforced schemas and relationships, queried with SQL.",
 "context": "The default choice for fifty years for good reason: the relational model (Codd, 1970) gives a clean mathematical foundation, and ACID transactions make correctness the engine's problem rather than yours. Postgres, MySQL, Oracle, SQL Server are the household names.",
 "see_also": ["Database", "SQL", "Relation", "Normalization", "Transaction", "Join"]},

{"term": "SQL", "branch": "Data & Databases", "aliases": ["Structured Query Language"],
 "tags": ["fundamental"], "wikipedia": "SQL",
 "def": "The declarative language for querying and manipulating relational data — you state *what* you want and the engine's query planner decides *how* to fetch it.",
 "context": "Declarative is the whole point: the optimiser is free to use indexes, reorder joins, and parallelise without you rewriting the query. Standardised (SQL-92 onward) but every vendor adds dialect, so portability is partial.",
 "see_also": ["RDBMS", "Query Optimizer", "Join", "Index", "NoSQL"],
 "confused": [("NoSQL", "SQL names a query language; NoSQL names a category of stores, many of which now offer SQL-like languages anyway.")]},

{"term": "NoSQL", "branch": "Data & Databases", "aliases": ["Not Only SQL"],
 "tags": [], "wikipedia": "NoSQL",
 "def": "An umbrella for non-relational stores — key-value, document, column-family, and graph — that trade the relational model and often strict consistency for scale, flexible schemas, or specific access patterns.",
 "context": "Born from web-scale needs the relational model served awkwardly. The name is a misnomer: it's a grab-bag of very different tools (Redis, MongoDB, Cassandra, Neo4j) whose only shared trait is 'not a classic RDBMS'. Pick by access pattern, not by hype.",
 "see_also": ["Database", "CAP Theorem", "Eventual Consistency", "Key-Value Store", "Document Database"],
 "confused": [("RDBMS", "Not a replacement but a different toolset; most systems use both, relational for the source of truth and NoSQL for caches, search, or specific workloads.")]},

{"term": "ACID", "branch": "Data & Databases", "aliases": ["Atomicity Consistency Isolation Durability"],
 "tags": ["fundamental"], "wikipedia": "ACID",
 "def": "The four guarantees of a reliable transaction: **A**tomicity (all-or-nothing), **C**onsistency (valid state to valid state), **I**solation (concurrent transactions don't corrupt each other), **D**urability (committed data survives crashes).",
 "context": "What lets you reason about a database as if you were the only user even when thousands aren't. Isolation is the subtle one — full serialisability is expensive, so engines offer weaker levels (read committed, repeatable read) with documented anomalies.",
 "see_also": ["Transaction", "Isolation Level", "BASE", "MVCC", "Durability"],
 "confused": [("BASE", "ACID prioritises correctness and consistency; BASE deliberately relaxes them for availability and scale.")]},

{"term": "BASE", "branch": "Data & Databases", "aliases": ["Basically Available Soft-state Eventual consistency"],
 "tags": [], "wikipedia": "Eventual consistency",
 "def": "The consistency philosophy of many distributed NoSQL systems: **B**asically **A**vailable, **S**oft state, **E**ventual consistency — accept temporary inconsistency in exchange for availability and partition tolerance.",
 "context": "A deliberate, half-joking counterpoint to ACID (acid vs. base). It's the CAP theorem made into a design stance: when the network partitions, stay available and reconcile later.",
 "see_also": ["ACID", "Eventual Consistency", "CAP Theorem", "NoSQL"]},

{"term": "CAP Theorem", "branch": "Data & Databases", "aliases": ["Brewer's Theorem"],
 "tags": ["fundamental"], "wikipedia": "CAP theorem",
 "def": "In a distributed data store, when a network **P**artition happens you can keep **C**onsistency or **A**vailability but not both — you can have at most two of consistency, availability, and partition tolerance.",
 "context": "Often mis-stated as 'pick two of three'. Since partitions are a fact of networks, not a choice, the real decision is CP vs AP *during a partition*. Modern systems make this tunable per operation rather than as a global stance.",
 "see_also": ["Eventual Consistency", "BASE", "Partition Tolerance", "Distributed System", "PACELC"],
 "links": ["[CAP theorem critique — Martin Kleppmann](https://martin.kleppmann.com/2015/05/11/please-stop-calling-databases-cp-or-ap.html)"]},

{"term": "Index", "branch": "Data & Databases", "tags": ["fundamental"], "wikipedia": "Database index",
 "def": "An auxiliary data structure (usually a B-tree) that lets the engine find rows by a key without scanning the whole table — trading write speed and disk space for read speed.",
 "context": "The single biggest lever on query performance, and the most common thing missing when a query is slow. Every index must be updated on every write, so they're not free; the art is indexing exactly the columns your queries filter and sort on.",
 "see_also": ["B-tree", "Query Optimizer", "Full Table Scan", "Composite Index", "Cardinality"]},

{"term": "Join", "branch": "Data & Databases", "tags": ["fundamental"], "wikipedia": "Join (SQL)",
 "def": "An operation combining rows from two or more tables on a related column — inner (matches only), left/right outer (keep unmatched on one side), cross (cartesian product).",
 "context": "The relational model's superpower: store each fact once, recombine on demand. Join performance is why indexes on join keys matter, and the cost of joins at scale is a big part of why denormalisation and NoSQL exist.",
 "see_also": ["RDBMS", "Normalization", "Foreign Key", "Index", "Query Optimizer"]},

{"term": "Normalization", "branch": "Data & Databases", "de": "Normalisierung", "tags": [], "wikipedia": "Database normalization",
 "def": "Structuring a relational schema to eliminate redundancy by decomposing tables so each fact is stored exactly once, governed by a series of **normal forms** (1NF, 2NF, 3NF, BCNF…).",
 "context": "Normalise for write integrity (no update anomalies); *denormalise* deliberately for read performance once you've measured a problem. 3NF is the usual practical target. 'Normalise till it hurts, denormalise till it works.'",
 "see_also": ["RDBMS", "Join", "Denormalization", "Foreign Key", "Primary Key"],
 "confused": [("Denormalization", "Normalization removes redundancy for integrity; denormalization reintroduces it on purpose for read speed.")]},

{"term": "Transaction", "branch": "Data & Databases", "de": "Transaktion", "tags": ["fundamental"], "wikipedia": "Database transaction",
 "def": "A unit of work executed as a single atomic, isolated operation — it either fully commits or fully rolls back, leaving the database consistent either way.",
 "context": "The abstraction that lets you bundle 'debit A, credit B' so a crash between them can't lose money. The ACID guarantees are exactly the transaction's promises. In distributed systems, multi-node transactions are the hard, expensive case.",
 "see_also": ["ACID", "Commit", "Rollback", "Isolation Level", "Two-phase Commit"]},

{"term": "Sharding", "branch": "Data & Databases", "tags": ["modern"], "wikipedia": "Shard (database architecture)",
 "def": "Horizontally partitioning a dataset across multiple machines by a **shard key**, so each node holds a subset — the main way to scale writes beyond one server.",
 "context": "Scales out where vertical scaling (a bigger box) hits a wall, but the shard key is a near-irreversible decision: pick badly and you get hotspots or cross-shard queries that defeat the purpose. Cross-shard transactions and joins are the recurring pain.",
 "see_also": ["Replication", "Partition", "Horizontal Scaling", "Consistent Hashing"],
 "confused": [("Replication", "Sharding splits data across nodes for capacity; replication copies the same data to nodes for availability and read scaling.")]},

{"term": "Replication", "branch": "Data & Databases", "de": "Replikation", "tags": [], "wikipedia": "Replication (computing)",
 "def": "Maintaining copies of data on multiple nodes for availability, read scaling, and durability — synchronous (wait for replicas) or asynchronous (don't).",
 "context": "Sync replication gives stronger consistency at the cost of latency; async is faster but replicas lag, so a read from a replica can be stale. The leader/follower (primary/replica) topology is the common shape, with failover promoting a follower when the leader dies.",
 "see_also": ["Sharding", "Eventual Consistency", "Failover", "Leader Election", "Replication Lag"]},

{"term": "B-tree", "branch": "Data & Databases", "tags": ["fundamental"], "wikipedia": "B-tree",
 "def": "A self-balancing, multi-way search tree that keeps data sorted and supports search, insert, and delete in logarithmic time — designed so each node is one disk page.",
 "context": "The reason it dominates database and filesystem indexes: it's *disk-aware*. A high branching factor means a few page reads reach any record, minimising the expensive operation (I/O). The B+tree variant, with all values in the leaves linked for range scans, is what most engines actually use.",
 "see_also": ["Index", "LSM Tree", "Binary Search Tree", "Disk I/O"],
 "confused": [("Binary Search Tree", "A BST is binary and memory-oriented; a B-tree is wide and disk-oriented, with many keys per node to minimise page reads.")]},

{"term": "MVCC", "branch": "Data & Databases", "aliases": ["Multiversion Concurrency Control"],
 "tags": [], "wikipedia": "Multiversion concurrency control",
 "def": "A concurrency technique where writes create new versions of rows rather than overwriting, so readers see a consistent snapshot without blocking writers (and vice versa).",
 "context": "Why Postgres readers don't block writers. The cost is bloat — old versions must be garbage-collected (Postgres's VACUUM), and long-running transactions hold old versions alive. The mechanism behind snapshot isolation.",
 "see_also": ["Transaction", "Isolation Level", "ACID", "Snapshot Isolation"]},

{"term": "ORM", "branch": "Data & Databases", "aliases": ["Object-Relational Mapping"],
 "tags": [], "wikipedia": "Object–relational mapping",
 "def": "A library that maps database rows to objects in your programming language, letting you query and persist data without writing raw SQL.",
 "context": "Productive for CRUD, but the abstraction leaks: the classic **N+1 query** problem and opaque generated SQL bite at scale. The 'object-relational impedance mismatch' it papers over is real. Know the SQL underneath, even when the ORM writes it.",
 "see_also": ["SQL", "RDBMS", "N+1 Problem", "Active Record Pattern"]},

{"term": "OLTP", "branch": "Data & Databases", "aliases": ["Online Transaction Processing"],
 "tags": [], "wikipedia": "Online transaction processing",
 "def": "Workloads dominated by many small, fast read/write transactions — order entry, banking, the operational database behind an app.",
 "context": "Optimised for low-latency point operations and high concurrency; row-oriented storage suits it. The counterpart to OLAP, and the reason analytics is usually run on a separate system rather than your production database.",
 "see_also": ["OLAP", "Transaction", "RDBMS", "Row-oriented Storage"],
 "confused": [("OLAP", "OLTP is many small transactions (running the business); OLAP is few large analytical scans (understanding the business).")]},

{"term": "OLAP", "branch": "Data & Databases", "aliases": ["Online Analytical Processing"],
 "tags": [], "wikipedia": "Online analytical processing",
 "def": "Workloads dominated by large aggregating queries over historical data — reporting, dashboards, analytics — typically on a data warehouse.",
 "context": "Optimised for scanning and aggregating columns across millions of rows; columnar storage (Parquet, ClickHouse, BigQuery) is the natural fit. Kept separate from OLTP so heavy analytics don't starve the operational system.",
 "see_also": ["OLTP", "Data Warehouse", "Column-oriented Storage", "Star Schema"]},

{"term": "Eventual Consistency", "branch": "Data & Databases", "tags": [], "wikipedia": "Eventual consistency",
 "def": "A consistency model guaranteeing that, absent new writes, all replicas will *eventually* converge to the same value — but a read may return stale data in the meantime.",
 "context": "The pragmatic consistency of large distributed systems (DNS, S3, shopping carts). Acceptable when stale-for-a-moment is fine; dangerous when it isn't (don't build a bank ledger on it). Read-your-writes and monotonic-read are stronger session guarantees layered on top.",
 "see_also": ["CAP Theorem", "BASE", "Strong Consistency", "Replication", "Conflict Resolution"],
 "confused": [("Strong Consistency", "Strong consistency: every read sees the latest write. Eventual: reads may lag but converge.")]},

{"term": "Primary Key", "branch": "Data & Databases", "tags": ["fundamental"], "wikipedia": "Primary key",
 "def": "The column(s) uniquely identifying each row in a table — non-null, unique, and the row's stable identity.",
 "context": "Choosing natural (a real attribute) vs surrogate (an auto-generated id like a UUID or sequence) keys is a perennial debate; surrogate usually wins for stability. The primary key typically backs a clustered index, shaping physical row order.",
 "see_also": ["Foreign Key", "Index", "UUID", "Composite Key"]},

{"term": "Foreign Key", "branch": "Data & Databases", "tags": ["fundamental"], "wikipedia": "Foreign key",
 "def": "A column referencing the primary key of another table, enforcing **referential integrity** — you can't reference a row that doesn't exist.",
 "context": "The database-level guarantee that relationships stay valid (no orphaned orders pointing at a deleted customer). Some high-scale systems drop them for write performance and enforce integrity in the application — a real tradeoff, not free.",
 "see_also": ["Primary Key", "Join", "Referential Integrity", "Normalization"]},

# ============================ PROGRAMMING LANGUAGES ============================
{"term": "Variable", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Variable (computer science)",
 "def": "A named binding to a storage location or value. Whether it names a mutable box or an immutable value depends entirely on the language.",
 "context": "The mutable-box mental model (C, Java) and the immutable-binding model (functional languages, Rust by default) diverge sharply, and the confusion when crossing languages is real. Scope and lifetime — where a name is visible and how long its value lives — are the deeper questions.",
 "see_also": ["Scope", "Reference", "Mutability", "Binding", "Lifetime"]},

{"term": "Pointer", "branch": "Programming Languages", "de": "Zeiger", "tags": ["fundamental"], "wikipedia": "Pointer (computer programming)",
 "def": "A value holding the memory address of another value. Dereferencing follows the address to read or write the target.",
 "context": "Power and footguns in one concept: pointer arithmetic, manual memory management, and the entire class of bugs (dangling pointers, use-after-free, null dereference) that memory-safe languages exist to abolish. Understanding pointers is understanding how memory actually works.",
 "see_also": ["Reference", "Dereference", "Null Pointer", "Memory Safety", "Dangling Pointer", "Pointer Arithmetic"],
 "confused": [("Reference", "A pointer is an explicit, manipulable address (you can do arithmetic, it can be null); a reference is a safer, usually-immutable alias the language manages.")]},

{"term": "Reference", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Reference (computer science)",
 "def": "An alias to a value — a handle that lets you access the original without copying it. Safer than a raw pointer: typically can't be null, can't do arithmetic, and is often managed by the language.",
 "context": "Pass-by-reference vs pass-by-value is a defining language semantics. 'Reference' means subtly different things in C++ (an alias), Java (a managed pointer), and Rust (a borrow with a checked lifetime) — the differences matter.",
 "see_also": ["Pointer", "Dereference", "Pass by Reference", "Borrowing", "Aliasing"]},

{"term": "Dereference", "branch": "Programming Languages", "tags": [], "wikipedia": "Dereference operator",
 "def": "Following a pointer or reference to access the value it points to.",
 "context": "The act where things go wrong: dereferencing null or a freed pointer is undefined behaviour in C/C++ and a crash (or worse, a vulnerability) elsewhere. The `*` in C, the implicit follow in most managed languages.",
 "see_also": ["Pointer", "Reference", "Null Pointer", "Undefined Behavior"]},

{"term": "Null Pointer", "branch": "Programming Languages", "aliases": ["Null Reference"],
 "tags": [], "wikipedia": "Null pointer",
 "def": "A pointer that points to nothing — a sentinel meaning 'no value'. Dereferencing one is a classic crash or security bug.",
 "context": "Tony Hoare called null his 'billion-dollar mistake'. Modern languages fight it structurally: option/maybe types (Rust's `Option`, Haskell's `Maybe`), nullable-type annotations (Kotlin, TypeScript), making 'might be absent' visible in the type rather than a runtime surprise.",
 "see_also": ["Null", "Pointer", "Option Type", "Memory Safety"],
 "links": ["[Null References: The Billion Dollar Mistake — Tony Hoare](https://www.infoq.com/presentations/Null-References-The-Billion-Dollar-Mistake-Tony-Hoare/)"]},

{"term": "Closure", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Closure (computer programming)",
 "def": "A function bundled together with the variables it captured from its surrounding scope — it 'closes over' that environment and can use those variables later, even after the enclosing function has returned.",
 "context": "The mechanism behind callbacks, decorators, and most functional patterns. The capture semantics — by value or by reference — are a frequent source of bugs (the classic 'loop variable captured by reference' surprise). Closures are how functions become genuinely first-class.",
 "see_also": ["First-class Function", "Scope", "Lambda", "Higher-order Function", "Lexical Scope"]},

{"term": "Recursion", "branch": "Programming Languages", "de": "Rekursion", "tags": ["fundamental"], "wikipedia": "Recursion (computer science)",
 "def": "A function that solves a problem by calling itself on smaller subproblems, with a base case to stop. The natural expression of self-similar (recursive) structures like trees.",
 "context": "Elegant for divide-and-conquer and tree traversal, but each call consumes stack — deep recursion overflows the stack unless the language does **tail-call optimisation**. Often equivalent to iteration, but some problems (tree walks, parsers) are far clearer recursively.",
 "see_also": ["Stack", "Tail Call", "Base Case", "Divide and Conquer", "Stack Overflow"]},

{"term": "Type System", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Type system",
 "def": "The rules by which a language assigns and checks **types**, catching whole classes of errors and enabling optimisation. The system's power and where it checks (compile time vs runtime) define much of a language's character.",
 "context": "A spectrum, not a binary: along static↔dynamic (when checked) and strong↔weak (how strictly). Rich static systems (Rust, Haskell, TypeScript) push more guarantees to compile time — 'make illegal states unrepresentable'. The cost is ceremony; the payoff is errors caught before they ship.",
 "see_also": ["Static Typing", "Dynamic Typing", "Strong Typing", "Type Inference", "Type Safety", "Generics"]},

{"term": "Static Typing", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Type system",
 "def": "Type checking performed at compile time — types are known and verified before the program runs.",
 "context": "Catches type errors before deployment and gives the compiler information for optimisation and tooling (autocomplete, refactoring). The tradeoff against dynamic typing is ceremony and flexibility vs. early safety; type inference (below) softens the verbosity.",
 "see_also": ["Dynamic Typing", "Type System", "Type Inference", "Compiler"],
 "confused": [("Dynamic Typing", "Static = types checked at compile time; dynamic = types checked at runtime. Orthogonal to strong/weak.")]},

{"term": "Dynamic Typing", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Type system",
 "def": "Type checking performed at runtime — a variable's type is a property of its current value, not a fixed declaration.",
 "context": "Fast to write and flexible (Python, Ruby, JavaScript), at the cost of type errors surfacing only when that code path runs. The industry's partial answer: gradual typing (type hints, TypeScript) bolting optional static checking onto dynamic languages.",
 "see_also": ["Static Typing", "Type System", "Duck Typing", "Gradual Typing"]},

{"term": "Type Inference", "branch": "Programming Languages", "tags": ["modern"], "wikipedia": "Type inference",
 "def": "The compiler deducing types automatically from context, so you get static-typing guarantees without writing every annotation.",
 "context": "What makes modern statically-typed languages feel light (Rust's `let`, Go's `:=`, `auto` in C++, Hindley-Milner in ML/Haskell). The guarantees of static typing without the verbosity — the reason the static-vs-dynamic ergonomics gap has narrowed.",
 "see_also": ["Static Typing", "Type System", "Hindley-Milner"]},

{"term": "Generics", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Generic programming",
 "def": "Writing code parameterised over types — a `List<T>` or `Vec<T>` that works for any element type while staying type-safe.",
 "context": "Lets you write an algorithm once for all types without sacrificing type checking or (with monomorphisation) performance. Implementation strategies differ sharply: monomorphisation (C++ templates, Rust — fast, code bloat) vs type erasure (Java — small, runtime cost).",
 "see_also": ["Type System", "Polymorphism", "Template", "Monomorphization", "Type Erasure"]},

{"term": "Polymorphism", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Polymorphism (computer science)",
 "def": "Code that operates on values of multiple types. The major kinds: **ad-hoc** (overloading), **parametric** (generics), and **subtype** (inheritance/interfaces).",
 "context": "The word covers three quite different mechanisms that beginners conflate. Subtype polymorphism (a `Dog` used where an `Animal` is expected) is the OOP one; parametric is generics; ad-hoc is operator/function overloading. Knowing which is which clarifies a lot of language design.",
 "see_also": ["Generics", "Inheritance", "Interface", "Dynamic Dispatch", "Duck Typing"]},

{"term": "Inheritance", "branch": "Programming Languages", "de": "Vererbung", "tags": [], "wikipedia": "Inheritance (object-oriented programming)",
 "def": "An OOP mechanism where a class derives fields and behaviour from a parent class, modelling an 'is-a' relationship.",
 "context": "Powerful but overused — deep hierarchies become brittle, and the modern guidance is 'favour composition over inheritance'. The fragile base class problem and the diamond problem (multiple inheritance) are why many newer languages prefer interfaces/traits and composition.",
 "see_also": ["Composition over Inheritance", "Polymorphism", "Interface", "Trait", "Liskov Substitution Principle"],
 "confused": [("Composition over Inheritance", "Inheritance reuses by subclassing (is-a); composition reuses by holding instances (has-a) and is usually more flexible.")]},

{"term": "Garbage Collection", "branch": "Programming Languages", "aliases": ["GC", "Automatic Memory Management"],
 "tags": ["fundamental"], "wikipedia": "Garbage collection (computer science)",
 "def": "Automatic reclamation of memory no longer reachable by the program, freeing the developer from manual `free()`/`delete` and the bugs that come with it.",
 "context": "Trades a class of memory bugs (leaks, use-after-free) for unpredictable **GC pauses** and higher memory use — a real problem for latency-sensitive systems. Tracing (mark-sweep, generational) vs reference counting are the two families; Rust's borrow checker is the notable 'neither' answer.",
 "see_also": ["Memory Safety", "Reference Counting", "Memory Leak", "RAII", "Stop-the-world"],
 "confused": [("RAII", "GC reclaims memory automatically at some later point; RAII ties resource release deterministically to scope exit, no collector needed.")]},

{"term": "RAII", "branch": "Programming Languages", "aliases": ["Resource Acquisition Is Initialization"],
 "tags": [], "wikipedia": "Resource acquisition is initialization",
 "def": "A C++ idiom (also Rust's core model) where a resource's lifetime is tied to an object's scope — acquired in the constructor, released deterministically in the destructor when the object goes out of scope.",
 "context": "The deterministic alternative to garbage collection: no collector, no pauses, and cleanup happens exactly when scope ends — covering memory, file handles, locks, sockets. Rust's ownership generalises this into a compile-time guarantee.",
 "see_also": ["Garbage Collection", "Ownership", "Destructor", "Scope", "Memory Safety"]},

{"term": "Memory Safety", "branch": "Programming Languages", "tags": ["modern"], "wikipedia": "Memory safety",
 "def": "The property that a program cannot access memory incorrectly — no buffer overflows, use-after-free, null dereferences, or data races on memory.",
 "context": "Around 70% of serious security vulnerabilities in C/C++ codebases (per Microsoft and Google data) are memory-safety bugs — the reason for the industry-wide push toward Rust and for CISA's memory-safety roadmap. Achieved via GC, or via Rust's borrow checker at compile time with no runtime cost.",
 "see_also": ["Pointer", "Buffer Overflow", "Ownership", "Borrowing", "Use-after-free", "Garbage Collection"],
 "links": ["[CISA — The Urgent Need for Memory Safety](https://www.cisa.gov/news-events/news/urgent-need-memory-safety-software-products)"]},

{"term": "Compiler", "branch": "Programming Languages", "de": "Compiler", "tags": ["fundamental"], "wikipedia": "Compiler",
 "def": "A program that translates source code in one language into another (usually machine code or bytecode) ahead of execution, typically performing optimisation along the way.",
 "context": "The classic phases — lexing, parsing to an AST, semantic analysis, optimisation, code generation — recur everywhere, not just in language compilers. Compile-time work is the price for runtime speed and early error detection. Contrast with interpreters, which translate as they run.",
 "see_also": ["Interpreter", "Bytecode", "AST", "JIT Compilation", "Lexer", "Optimization"],
 "confused": [("Interpreter", "A compiler translates the whole program ahead of time; an interpreter executes it directly, statement by statement.")]},

{"term": "Interpreter", "branch": "Programming Languages", "tags": ["fundamental"], "wikipedia": "Interpreter (computing)",
 "def": "A program that executes source code directly, translating and running it statement by statement rather than compiling to machine code first.",
 "context": "Faster startup and easier debugging (no compile step), slower steady-state execution. The line is blurry: most 'interpreted' languages (Python, JS) compile to bytecode first, and JIT compilation makes the dichotomy a spectrum.",
 "see_also": ["Compiler", "Bytecode", "JIT Compilation", "REPL"]},

{"term": "Bytecode", "branch": "Programming Languages", "tags": [], "wikipedia": "Bytecode",
 "def": "A compact, portable intermediate instruction set for a virtual machine — between human-readable source and native machine code.",
 "context": "The 'compile once, run anywhere' enabler: JVM bytecode, .NET CIL, Python's .pyc, WebAssembly. A VM either interprets it or JIT-compiles it to native code at runtime, decoupling the language from the hardware.",
 "see_also": ["Virtual Machine", "JIT Compilation", "Compiler", "WASM", "JVM"]},

{"term": "JIT Compilation", "branch": "Programming Languages", "aliases": ["Just-in-Time Compilation"],
 "tags": ["modern"], "wikipedia": "Just-in-time compilation",
 "def": "Compiling bytecode to native machine code at runtime, often guided by profiling of which paths are actually hot — blending interpretation's flexibility with compilation's speed.",
 "context": "Why modern JavaScript (V8) and Java (HotSpot) are fast despite being 'interpreted'. The runtime can optimise using information a static compiler never has — actual hot paths and observed types — at the cost of warm-up time and memory.",
 "see_also": ["Bytecode", "Compiler", "Interpreter", "AOT Compilation", "Profile-guided Optimization"]},

{"term": "AST", "branch": "Programming Languages", "aliases": ["Abstract Syntax Tree"],
 "tags": [], "wikipedia": "Abstract syntax tree",
 "def": "A tree representation of source code's structure, produced by the parser, abstracting away syntactic noise (parentheses, semicolons) into the essential grammar.",
 "context": "The data structure nearly all code tooling operates on — compilers, linters, formatters (Prettier), refactoring tools, and codemods all walk the AST rather than raw text. Understanding it demystifies how 'magic' dev tools work.",
 "see_also": ["Compiler", "Parser", "Lexer", "Context-free Grammar"]},

{"term": "Lambda", "branch": "Programming Languages", "aliases": ["Anonymous Function", "Lambda Expression"],
 "tags": [], "wikipedia": "Anonymous function",
 "def": "A function defined inline without a name, often passed as an argument — `x => x + 1`.",
 "context": "Now ubiquitous (even Java and C++ have them), the workhorse of functional-style code: map/filter/reduce, callbacks, event handlers. Closely tied to closures, since lambdas usually capture their surrounding scope. Named after Church's lambda calculus.",
 "see_also": ["Closure", "First-class Function", "Higher-order Function", "Lambda Calculus"]},

{"term": "Pure Function", "branch": "Programming Languages", "tags": [], "wikipedia": "Pure function",
 "def": "A function whose output depends only on its inputs and which has no side effects — same input always yields same output, and nothing observable changes outside it.",
 "context": "The cornerstone of functional programming and the reason pure code is trivially testable, cacheable (memoisable), and parallelisable. Real programs need side effects somewhere; the discipline is pushing them to the edges and keeping the core pure.",
 "see_also": ["Side Effect", "Referential Transparency", "Functional Programming", "Memoization", "Idempotent"],
 "confused": [("Idempotent", "Pure: no side effects at all. Idempotent: a side effect that's safe to repeat (calling twice == calling once).")]},

{"term": "Side Effect", "branch": "Programming Languages", "tags": [], "wikipedia": "Side effect (computer science)",
 "def": "Any observable change a function makes beyond returning a value — mutating state, I/O, network calls, writing to a database.",
 "context": "Not bad, but the source of most complexity in reasoning about code: a function with side effects can't be understood in isolation. Functional programming's whole project is isolating and controlling them (monads, effect systems) so the rest stays pure and predictable.",
 "see_also": ["Pure Function", "Referential Transparency", "Monad", "State"]},

{"term": "Concurrency", "branch": "Programming Languages", "de": "Nebenläufigkeit", "tags": ["fundamental"], "wikipedia": "Concurrency (computer science)",
 "def": "Structuring a program as multiple independent tasks that can make progress in overlapping time periods — about *dealing with* many things at once, even on one core.",
 "context": "Rob Pike's distinction is the one to internalise: concurrency is composition of independently executing things; parallelism is doing things simultaneously. You can have concurrency on a single core (via interleaving) and you need it before parallelism helps.",
 "see_also": ["Parallelism", "Thread", "Async/Await", "Race Condition", "Coroutine"],
 "confused": [("Parallelism", "Concurrency is about structure (many tasks in flight, possibly interleaved); parallelism is about execution (many tasks literally running at once on multiple cores).")]},

{"term": "Parallelism", "branch": "Programming Languages", "de": "Parallelität", "tags": [], "wikipedia": "Parallel computing",
 "def": "Actually executing multiple computations simultaneously, on multiple cores or machines — about *doing* many things at once for speed.",
 "context": "Bounded by Amdahl's law: the serial fraction caps your speedup no matter how many cores you add. Requires concurrency as a precondition but is a distinct goal — concurrency is the structure, parallelism is the simultaneous execution.",
 "see_also": ["Concurrency", "Amdahl's Law", "Thread", "SIMD", "Data Parallelism"]},

{"term": "Async/Await", "branch": "Programming Languages", "tags": ["modern"], "wikipedia": "Async/await",
 "def": "Language syntax for writing asynchronous, non-blocking code that *reads* like sequential code — `await` suspends until a result is ready without blocking the thread.",
 "context": "The mainstream answer to callback hell, now in JS, Python, Rust, C#. Underneath sits an event loop or executor and (often) coroutines. The classic trap: 'function colouring' — async infects callers, so a sync function can't easily call an async one.",
 "see_also": ["Coroutine", "Concurrency", "Event Loop", "Future", "Non-blocking I/O"]},

{"term": "Coroutine", "branch": "Programming Languages", "tags": [], "wikipedia": "Coroutine",
 "def": "A function that can suspend and resume its execution, preserving local state across suspensions — cooperative, lightweight, and not tied to an OS thread.",
 "context": "The building block under async/await and Go's goroutines. Cheap compared to OS threads (you can have millions), they multiplex onto a few threads via an event loop or scheduler. Cooperative scheduling means one coroutine that never yields can starve the rest.",
 "see_also": ["Async/Await", "Thread", "Green Threads", "Generator", "Concurrency"]},

{"term": "Undefined Behavior", "branch": "Programming Languages", "aliases": ["UB"],
 "tags": [], "wikipedia": "Undefined behavior",
 "def": "Code whose result the language spec leaves entirely unconstrained — the compiler may do anything, including silently miscompile, crash, or appear to work.",
 "context": "The C/C++ minefield: signed overflow, out-of-bounds access, data races, null dereference. Crucially, optimisers *assume UB never happens* and rewrite code on that assumption, so UB can corrupt code far from the bug. A core motivator for memory-safe languages.",
 "see_also": ["Memory Safety", "Pointer", "Optimization", "Sanitizer"]},
]
